// Generated by progression/tools/capstones.py: capstone recipes and reward on right-click.
ServerEvents.recipes(event => {
  event.custom({"type":"minecraft:crafting_shapeless","ingredients":[{"item":"minecraft:stone_pickaxe"},{"item":"minecraft:bread"},{"tag":"minecraft:beds"},{"item":"minecraft:paper"}],"result":{"id":"kubejs:settlers_charter","count":1}}).id("progression:capstone/settlers_charter")
  event.custom({"type":"minecraft:crafting_shapeless","ingredients":[{"item":"storagedrawers:oak_full_drawers_1"},{"item":"natura:maple_sapling"},{"item":"minecraft:trial_key"},{"item":"minecraft:paper"}],"result":{"id":"kubejs:homestead_seal","count":1}}).id("progression:capstone/homestead_seal")
  event.custom({"type":"minecraft:crafting_shapeless","ingredients":[{"item":"tconstruct:seared_brick"},{"item":"botania:livingrock"},{"item":"minecraft:wet_sponge"},{"item":"minecraft:paper"}],"result":{"id":"kubejs:engineers_compact","count":1}}).id("progression:capstone/engineers_compact")
  event.custom({"type":"minecraft:crafting_shapeless","ingredients":[{"item":"enderio:dark_steel_ingot"},{"item":"bloodmagic:slate_reinforced"},{"item":"minecraft:blaze_rod"},{"item":"minecraft:paper"}],"result":{"id":"kubejs:nether_accord","count":1}}).id("progression:capstone/nether_accord")
  event.custom({"type":"minecraft:crafting_shapeless","ingredients":[{"item":"draconicevolution:draconium_ingot"},{"type":"botania:ore","ore":"ingotTerrasteel"},{"item":"twilightforest:lich_trophy"},{"item":"aether:victory_medal"},{"item":"minecraft:paper"}],"result":{"id":"kubejs:realm_key","count":1}}).id("progression:capstone/realm_key")
  event.custom({"type":"minecraft:crafting_shapeless","ingredients":[{"item":"draconicevolution:awakened_core"},{"item":"botania:gaia_head"},{"item":"draconicevolution:chaos_shard"},{"item":"minecraft:paper"}],"result":{"id":"kubejs:mastery_crown","count":1}}).id("progression:capstone/mastery_crown")
  // Bountiful decrees (Hexxit II port): the capstone is kept, the decree unlocks that age bounties on a board
  if (Item.exists("bountiful:decree_settler")) event.shapeless("bountiful:decree_settler", ["kubejs:settlers_charter", "minecraft:paper", "minecraft:ink_sac", "minecraft:gold_nugget"]).keepIngredient("kubejs:settlers_charter").id("progression:decree/settler")
  if (Item.exists("bountiful:decree_homestead")) event.shapeless("bountiful:decree_homestead", ["kubejs:homestead_seal", "minecraft:paper", "minecraft:ink_sac", "minecraft:gold_nugget"]).keepIngredient("kubejs:homestead_seal").id("progression:decree/homestead")
  if (Item.exists("bountiful:decree_engineer")) event.shapeless("bountiful:decree_engineer", ["kubejs:engineers_compact", "minecraft:paper", "minecraft:ink_sac", "minecraft:gold_nugget"]).keepIngredient("kubejs:engineers_compact").id("progression:decree/engineer")
  if (Item.exists("bountiful:decree_nether")) event.shapeless("bountiful:decree_nether", ["kubejs:nether_accord", "minecraft:paper", "minecraft:ink_sac", "minecraft:gold_nugget"]).keepIngredient("kubejs:nether_accord").id("progression:decree/nether")
  if (Item.exists("bountiful:decree_realm")) event.shapeless("bountiful:decree_realm", ["kubejs:realm_key", "minecraft:paper", "minecraft:ink_sac", "minecraft:gold_nugget"]).keepIngredient("kubejs:realm_key").id("progression:decree/realm")
  if (Item.exists("bountiful:decree_mastery")) event.shapeless("bountiful:decree_mastery", ["kubejs:mastery_crown", "minecraft:paper", "minecraft:ink_sac", "minecraft:gold_nugget"]).keepIngredient("kubejs:mastery_crown").id("progression:decree/mastery")
})

const CAPSTONES = {
  "kubejs:settlers_charter": { age: 1, name: "Settler's Charter", next: "Age 2: Homestead" },
  "kubejs:homestead_seal": { age: 2, name: "Homestead Seal", next: "Age 3: Iron & Tinkering" },
  "kubejs:engineers_compact": { age: 3, name: "Engineer's Compact", next: "Age 4: Nether & Power" },
  "kubejs:nether_accord": { age: 4, name: "Nether Accord", next: "Age 5: New Worlds" },
  "kubejs:realm_key": { age: 5, name: "Realm Key", next: "Age 6: Mastery" },
  "kubejs:mastery_crown": { age: 6, name: "Mastery Crown", next: "the end of the guide" },
}

const RING = {
 "1": "Next: Homestead. Look within 1,500 blocks of spawn: Battle Tower lower floors, ruins, small dungeons and villages with bounty boards.",
 "2": "Next: Iron & Tinkering. Travel 1,500 to 4,000 blocks out for tier-1 and tier-2 dungeons, Battle Tower tops and mineshafts.",
 "3": "Next: Nether & Power. Prepare the Nether, Deep Below and the Wyvern Lair; the 4,000-block ring has tier-3 castles.",
 "4": "Next: New Worlds. The Twilight Forest, the Aether and the End are open, and the 4,000+ ring waits.",
 "5": "Next: Mastery. Gaia, the Chaos Guardian and the final castles; elite mobs roam beyond 4,000 blocks.",
 "6": "You finished the guide. The Mastery Crown is your trophy."
}

ItemEvents.rightClicked(event => {
  const id = String(event.item.id)
  const cap = CAPSTONES[id]
  if (!cap || event.hand != "main_hand") return
  const player = event.player
  if (player.persistentData.getBoolean("progression_reward_" + cap.age)) { player.tell(Text.gold(cap.name + ": you already claimed this reward. Keep it for the bounty decree.")); return }
  player.persistentData.putBoolean("progression_reward_" + cap.age, true)
  event.server.runCommandSilent("loot give " + player.username + " loot progression:rewards/age_" + cap.age)
  event.server.runCommandSilent("loot give " + player.username + " loot progression:rewards/hint_" + cap.age)
  player.tell(Text.gray(RING[cap.age]))
  player.tell(Text.gold(cap.name + " rewards you. Next: " + cap.next + "."))
  event.server.runCommandSilent("playsound minecraft:ui.toast.challenge_complete master " + player.username)
})
